const projects=[
{title:'Plateforme de cours en ligne',description:'Une plateforme e-learning avec un frontend React et un backend Django.',tags:['React','Django'],category:'web',tone:'#334b3d',label:'E-learning',ui:'Mes formations'},
{title:'EMSI-ECO',description:'Un site e-commerce dédié à la vente de produits écologiques.',tags:['PHP','Laravel'],category:'web',tone:'#525a39',label:'E-commerce',ui:'Une sélection plus verte'},
{title:'Gestion hôtelière',description:'Conception d’un système de gestion d’hôtel en Java / JEE.',tags:['Java','JEE'],category:'gestion',tone:'#4a4240',label:'Gestion',ui:'Gestion de l’hôtel'},
{title:'Cabinet médical',description:'Une application de gestion conçue pour un cabinet médical.',tags:['C#','.NET'],category:'gestion',tone:'#354f53',label:'Santé',ui:'Espace cabinet médical'},
{title:'Gestion immobilière',description:'Une plateforme pour la gestion des biens immobiliers et de leurs données associées.',tags:['Python','Django','MySQL','HTML / CSS'],category:'gestion',tone:'#4b4935',label:'Immobilier',ui:'Les biens immobiliers'},
{title:'Application météo',description:'Une application web météo développée en JavaScript avec Node.js.',tags:['JavaScript','Node.js','HTML / CSS'],category:'web',tone:'#354254',label:'Application web',ui:'Votre espace météo'},
{title:'Notation des professeurs',description:'Une plateforme de notation des professeurs développée avec Django REST Framework.',tags:['Django','Django REST Framework'],category:'web',tone:'#434234',label:'Éducation',ui:'Plateforme de notation'}];
const grid=document.querySelector('#project-grid');
function render(filter='all'){grid.innerHTML=projects.map((p,i)=>({...p,i})).filter(p=>filter==='all'||p.category===filter).map(p=>`<article class="project"><div class="project-visual" style="--tone:${p.tone}" aria-hidden="true"><span class="project-number">0${p.i+1} / CONCEPT D’INTERFACE</span><span class="project-type">${p.label.toUpperCase()}</span><div class="mini-window"><div class="mini-bar"><i></i><i></i><i></i></div><div class="mini-body"><div class="mini-side"><b></b><b></b><b></b><b></b></div><div class="mini-main"><div class="mini-heading">${p.ui}<span>Vue d’ensemble</span></div><div class="mini-sub"></div><div class="mini-tiles"><div class="mini-tile"><i></i><b></b></div><div class="mini-tile"><i></i><b></b></div><div class="mini-tile"><i></i><b></b></div></div></div></div></div></div><div class="project-info"><div class="project-title"><h3>${p.title}</h3><button data-project="${p.i}" aria-label="Découvrir le projet ${p.title}">↗</button></div><p>${p.description}</p><div class="tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div></div></article>`).join('')}
render();document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');render(button.dataset.filter)}));
const dialog=document.querySelector('dialog');grid.addEventListener('click',event=>{const button=event.target.closest('[data-project]');if(!button)return;const p=projects[Number(button.dataset.project)];document.querySelector('#dialog-title').textContent=p.title;document.querySelector('#dialog-description').textContent=p.description;document.querySelector('#dialog-tags').innerHTML=p.tags.map(t=>`<span>${t}</span>`).join('');dialog.showModal()});document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelector('#year').textContent=new Date().getFullYear();document.querySelector('#copy-email').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText('lakradhamza606@gmail.com');status.textContent='Adresse e-mail copiée !'}catch{status.textContent='Adresse : lakradhamza606@gmail.com'}});
